async function seedGrimmStories() {
  const client = await pool.connect();
  console.log(`Seeding ${grimmStories.length} new Grimm stories...`);

  try {
    await client.query('BEGIN');
    
    for (const story of grimmStories) {
      const result = await client.query(
        'INSERT INTO books (title, author, description, cover_url, file_path, category, content) VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING id',
        [story.title, story.author, story.description, '', '', story.category, story.content]
      );
      console.log(`  Inserted: ${story.title} (id: ${result.rows[0].id}, ${story.content.length} chars)`);
    }

    await client.query('COMMIT');

    const { rows: stats } = await client.query(`
      SELECT COUNT(*) as total,
             COUNT(CASE WHEN LENGTH(content) >= 800 THEN 1 END) as good,
             COUNT(CASE WHEN LENGTH(content) < 800 THEN 1 END) as short,
             AVG(LENGTH(content))::int as avg_len
      FROM books WHERE category = '格林童话'
    `);
    console.log(`\nDatabase stats: ${stats[0].total} total, ${stats[0].good} good (800+ chars), ${stats[0].short} short, avg ${stats[0].avg_len} chars`);

  } finally {
    client.release();
    await pool.end();
  }
}

seedGrimmStories().catch(console.error);